public class Main {
    public static void main(String[] args) {
        Object[] items = {"hello", 42, "world", 7};
        int total = 0, texts = 0;
        for (Object o : items) {
            if (o instanceof Integer) {
                total += (Integer) o;
            } else if (o instanceof String) {
                texts++;
            }
        }
        System.out.println("Total: " + total + " Texts: " + texts);
    }
}
